"""Lecture 28 vignette pool A -- Cardiomyopathy: dilated cardiomyopathy and the
population / rehabilitative / palliative strategies.

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.

Patient vignettes with a varied lead-in (the lead-in decides the answer).
Slides only; no recording exists yet (lecture 2026-10-01). Ejection fractions
in stems sit far from 40% (the deck's "<40%" against the 2022 bands). Digoxin
is never keyed for dilated cardiomyopathy, and nothing here uses hypertrophy as
a dilated-cardiomyopathy discriminator (slides 18 vs 37 disagree). Scope caps
live in cms_e5l28_scope.py.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e5l28_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d

def M(d, mis):
    """Attach the misconception each distractor stands for (WRITER.md rule 5), keyed by option text."""
    d["mis"] = mis
    return d


